class ParserError(ValueError):
    pass


def parse_with_format(value, fmt):
    if fmt == 'YYYYMMDD':
        year = int(value[0:4])
        month = int(value[4:6])
        day = int(value[6:8])
        if month < 1 or month > 12:
            raise ValueError('month must be in 1..12')
        return year, month, day
    if fmt == 'YYYY.M.D':
        year = int(value[0:4])
        month = int(value[4:6])
        day = int(value[6:8])
        if month < 1 or month > 12:
            raise ValueError('month must be in 1..12')
        return year, month, day
    raise ParserError('unsupported format')


def get(value, formats):
    for fmt in formats:
        try:
            return parse_with_format(value, fmt)
        except ParserError:
            continue
    raise ParserError('Could not match input to any format')
